visible_check:
from binning import histogram
for values, edges in (([-5], [0, 10, 20]), ([25], [0, 10, 20]), ([3, -0.5], [0, 2, 4])):
    try:
        histogram(values, edges)
    except ValueError:
        pass
    else:
        raise AssertionError(f"histogram({values!r}, {edges!r}) should raise ValueError")

